-- =============================================================================
-- Studuel — Migration 333 : ANGLAIS 6e — LE PROGRAMME DE LANGUE (21 fiches)
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 333 --modules anglais-6e
--
-- CONSTAT : l'anglais de 6e n'avait que les 5 fiches du premier jeu de données, et
-- cinq de ses leçons « Exercices types » n'avaient aucun quiz (traité par la 331).
-- Maigre ET trouée : avec l'histoire-géo de 4e, l'un des deux seuls points du tronc
-- commun dans ce cas, donc l'un des deux plus dangereux de l'app.
-- Cette migration installe 21 fiches rangées sous les 4 chapitres de langue (le
-- groupe nominal, le groupe verbal, les temps, la phrase) et retire les 5 fiches
-- génériques.
-- ÉCRIT, PAS IMPORTÉ DE LA 4e, et c'est un choix : le dépôt importe les langues
-- d'un niveau à l'autre parce que le BO les rédige pour le CYCLE 4 entier. La 6e
-- relève du CYCLE 3 et vise le niveau A1. Les 41 fiches de 4e portent le present
-- perfect, le past perfect, la voix passive et le discours indirect — devant un
-- élève de onze ans, ce n'est pas de l'avance, c'est un mur.
--
-- Cette migration apporte : 21 chapitres, 21 leçons,
-- 21 quiz et 168 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [anglais] La colonne chapters.theme (migration 234) conditionne tout ce qui suit : ce
-- [anglais] module range ses 21 fiches sous 4 chapitres, et l'INSERT écrit la colonne. Elle
-- [anglais] est REPRISE ici en ADD COLUMN IF NOT EXISTS parce qu'on ne peut pas garantir que
-- [anglais] la 234 soit passée en production — sans cette reprise, la migration échouerait
-- [anglais] sur "column chapters.theme does not exist", les 5 anciens chapitres déjà
-- [anglais] supprimés et les 21 neufs pas encore posés : une matière vide.
-- [anglais] Le GRANT n'est pas décoratif : la migration 182 a révoqué le SELECT de table sur
-- [anglais] chapters et ne l'a rendu que colonne par colonne.
ALTER TABLE public.chapters ADD COLUMN IF NOT EXISTS theme TEXT;
GRANT SELECT (theme) ON public.chapters TO anon;
GRANT SELECT (theme) ON public.chapters TO authenticated;

-- [anglais] Les 5 chapitres hérités partent, au niveau 6e SEULEMENT.
-- [anglais] 
-- [anglais] LE REPÈRE EST theme IS NULL, PAS LE TITRE : le critère « pas de chapitre de
-- [anglais] programme » vise exactement les cinq lignes voulues. Elles datent d'avant la
-- [anglais] colonne theme, tandis que les 21 fiches neuves en portent une dès l'INSERT — le
-- [anglais] ménage tourne AVANT les insertions et ne peut donc jamais mordre sur elles, ni
-- [anglais] au premier passage ni au rejeu.
-- [anglais] Le filtre level = '6e' est indispensable : l'anglais existe sur sept niveaux, et
-- [anglais] la 4e comme la 3e ont leurs propres migrations.
-- [anglais] L'ordre compte : la file "À revoir" d'abord (review_items.item_id n'a PAS de clé
-- [anglais] étrangère), puis les quiz (quizzes.lesson_id est ON DELETE SET NULL), puis les
-- [anglais] chapitres, dont les leçons partent en cascade.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'anglais'
   AND c.level = '6e'
   AND c.theme IS NULL;

DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'anglais'
   AND c.level = '6e'
   AND c.theme IS NULL;

DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'anglais'
   AND c.level = '6e'
   AND c.theme IS NULL;

-- 1. Chapitres -------------------------------------------------------------
