-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('10c1d7fd-2400-509b-947b-464d4b041969'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a box » ?', 'mcq', '["boxes","boxs","boxies","box"]'::jsonb, 0, 'Les noms en -x prennent -es.', 1),
    ('50bdb442-59f5-5a16-8700-608464d8225a'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a city » ?', 'mcq', '["cities","citys","cityes","city"]'::jsonb, 0, 'Consonne + y → -ies.', 2),
    ('c144b182-5dd5-59a4-87b8-962c2b29085f'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a boy » ?', 'mcq', '["boys","boies","boyes","boy"]'::jsonb, 0, 'Voyelle + y : le y reste.', 3),
    ('5d4120b6-e035-511b-913f-dc68fd016c9d'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a child » ?', 'mcq', '["children","childs","childes","childrens"]'::jsonb, 0, 'C’est un pluriel irrégulier.', 4),
    ('4f8dc446-3ac8-5b21-a17a-628038823a85'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a foot » ?', 'mcq', '["feet","foots","feets","footes"]'::jsonb, 0, 'Comme tooth → teeth.', 5),
    ('225b18ce-fbe3-53b9-a99f-c03729c049fd'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Comment dit-on « des informations » ?', 'mcq', '["some information","some informations","an information","informations"]'::jsonb, 0, '« Information » est indénombrable en anglais.', 6),
    ('3f94335f-5596-574d-9e47-48fdecf04259'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, 'Quel est le pluriel de « a knife » ?', 'mcq', '["knives","knifes","knifies","knife"]'::jsonb, 0, 'Les noms en -f / -fe font souvent -ves.', 7),
    ('76b3b5f2-73b6-5a59-b219-d8e67511778c'::uuid, 'b0c2aebe-43b9-50a0-b4fa-f30180db8644'::uuid, '« A sheep » a le même pluriel qu’au singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme « fish ».', 8),
    ('2dd18d33-b103-5689-9d77-4562d5a270b5'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Quel article place-t-on devant « apple » ?', 'mcq', '["an","a","the seulement","aucun"]'::jsonb, 0, 'Devant un son de voyelle.', 1),
    ('2def7b76-fcbf-53af-91fb-9d55f360d4a9'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Quel article place-t-on devant « university » ?', 'mcq', '["a","an","the obligatoirement","aucun"]'::jsonb, 0, 'On entend « you », donc un son de consonne.', 2),
    ('1ff21a1d-fdbc-5219-9339-1e862e58da4a'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Quel article place-t-on devant « hour » ?', 'mcq', '["an","a","the","aucun"]'::jsonb, 0, 'Le h ne se prononce pas : on entend une voyelle.', 3),
    ('8eb39189-34be-5601-bd66-615e6745947e'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Comment traduit-on « Les chats sont indépendants » ?', 'mcq', '["Cats are independent.","The cats are independent.","A cats are independent.","The cat are independent."]'::jsonb, 0, 'Pas d’article pour une généralité au pluriel.', 4),
    ('0c0087c5-34bd-5121-8dd8-4e22bbdc9437'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Comment dit-on « J’aime la musique » ?', 'mcq', '["I like music.","I like the music.","I like a music.","I like musics."]'::jsonb, 0, 'Pas d’article devant un indénombrable pris en général.', 5),
    ('627ad744-4984-5cef-981d-f80e25c4f28a'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Comment dit-on « aller à l’école » ?', 'mcq', '["go to school","go to the school","go to a school","go school"]'::jsonb, 0, 'Article zéro devant school pris dans sa fonction.', 6),
    ('921eed15-734d-57f8-a4f6-ce861b2bf240'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'Quel pays prend l’article « the » ?', 'mcq', '["the United States","France","Spain","Italy"]'::jsonb, 0, 'Comme the United Kingdom et the Netherlands.', 7),
    ('091a686e-15b8-5969-83cc-76aa95b92eee'::uuid, 'd93e8d60-c5cb-55c8-b6e6-f383547bf444'::uuid, 'On choisit entre « a » et « an » d’après la première lettre du mot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le SON qui décide, pas la lettre.', 8),
    ('b5b4e997-85f4-5250-a2b9-6806117a0f46'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Quel démonstratif pour un objet proche au singulier ?', 'mcq', '["this","that","these","those"]'::jsonb, 0, 'Proche + singulier.', 1),
    ('0c93f534-5c44-51f6-b3c9-dfcdcef2c7cd'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Quel démonstratif pour des objets éloignés au pluriel ?', 'mcq', '["those","these","that","this"]'::jsonb, 0, 'Éloigné + pluriel.', 2),
    ('e76aab83-ae46-5205-a4a6-ac550e633bda'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Comment traduit-on « Ces chaussures-ci sont neuves » ?', 'mcq', '["These shoes are new.","This shoes are new.","Those shoes are new.","That shoes are new."]'::jsonb, 0, 'Proche et pluriel.', 3),
    ('f9ff35bb-60b4-554b-a3af-d8ece03ba703'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Que dit-on au téléphone pour se présenter ?', 'mcq', '["This is Tom.","That is Tom.","These is Tom.","It is Tom here."]'::jsonb, 0, 'C’est un emploi figé de « this ».', 4),
    ('ac0782cb-c41d-55df-83ba-0079279e1fd3'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Quelles sont les deux questions à se poser avant de choisir ?', 'mcq', '["Proche ou éloigné, singulier ou pluriel","Masculin ou féminin","Sujet ou complément","Compté ou non compté"]'::jsonb, 0, 'Le français ne distingue que rarement la distance.', 5),
    ('1fc719b4-1569-5259-87ed-1ae9495a023b'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Comment traduit-on « ce matin » ?', 'mcq', '["this morning","that morning","these morning","those morning"]'::jsonb, 0, 'Le démonstratif sert aussi au temps.', 6),
    ('1ea9aaab-6c70-5c5c-9ed1-2660293446fb'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Quelle différence de prononciation entre « this » et « these » ?', 'mcq', '["« this » est court, « these » est long","Ils se prononcent pareil","« this » est long","Seule l’écriture change"]'::jsonb, 0, 'À l’oral, c’est le seul indice du nombre.', 7),
    ('8d5a8568-94b7-56f9-b91a-9681a9754d7f'::uuid, 'f585c87f-4e5b-5264-a8d2-d3b302554b51'::uuid, 'Un démonstratif doit toujours être suivi d’un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il peut s’employer seul : « What’s this? »', 8),
