    ('9bc0a8be-5892-5b9d-b07e-f761b7f87d8c'::uuid, 'bac84d48-fb26-5e4d-9148-a106f9b2a168'::uuid, 'Quelles sont les trois règles des modaux ?', 'mcq', '["Pas de -s, base verbale sans to, pas de DO","Toujours -s, avec to, avec DO","Pas de -s, avec to, avec DO","Toujours au passé"]'::jsonb, 0, 'Elles valent pour tous les modaux.', 6),
    ('d2375466-950c-5da0-af92-fd90038a23b1'::uuid, 'bac84d48-fb26-5e4d-9148-a106f9b2a168'::uuid, 'Comment dit-on « Je pourrai conduire l’an prochain » ?', 'mcq', '["I will be able to drive next year.","I will can drive next year.","I can drive next year.","I could drive next year."]'::jsonb, 0, '« Can » n’a pas d’infinitif : on passe par « be able to ».', 7),
